Object.assign(window.DYLEAN_DATA.files["Library/Init/Grind/Injective.lean"],{"text":"/-\nCopyright (c) 2025 Amazon.com, Inc. or its affiliates. All Rights Reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: Leonardo de Moura\n-/\nmodule\nprelude\npublic import Init.Data.Function\npublic import Init.NotationExtra\nimport Init.Classical\npublic section\nnamespace Lean.Grind\nopen Function\n\nnoncomputable def leftInv {α : Sort u} {β : Sort v} (f : α → β) (hf : Injective f) [Nonempty α] : β → α :=\n  Classical.choose hf.exists_leftInverse\n\ntheorem leftInv_eq {α : Sort u} {β : Sort v} (f : α → β) (hf : Injective f) [Nonempty α] (a : α) : leftInv f hf (f a) = a :=\n  Classical.choose_spec hf.exists_leftInverse a\n\n@[app_unexpander leftInv]\nmeta def leftInvUnexpander : PrettyPrinter.Unexpander := fun stx => do\n  match stx with\n  | `($_ $f:term $_) => `($f⁻¹)\n  | `($_ $f:term $_ $a:term) => `($f⁻¹ $a)\n  | _ => throw ()\n\nend Lean.Grind\n","refs":[[14,18,14,25,"bc88544f68b2",true],[14,70,14,79,"9f80519ab27c",false],[14,84,14,92,"f526d36ca536",false],[15,2,15,18,"d4e87c97f998",false],[15,22,15,40,"1a646800b4ee",false],[17,8,17,18,"d3989000122b",true],[17,63,17,72,"9f80519ab27c",false],[17,77,17,85,"f526d36ca536",false],[17,99,17,106,"bc88544f68b2",false],[18,2,18,23,"6ee299e2f886",false],[18,27,18,45,"1a646800b4ee",false],[20,17,20,24,"bc88544f68b2",false],[23,12,23,16,"e1d49401e172",false],[24,12,24,16,"e1d49401e172",false],[24,23,24,27,"e1d49401e172",false],[25,15,25,17,"8a0f209198a6",false]]});
